      return {
        success: false,
        message: handledSession.blockedReason ?? getAdminAccessLockMessage(),
        requiresLogin: false,
        email: normalizedEmail,
        accountType,
        ownerReviewRequired,
      };
    }
    authData.session = signInData.session;
  }
}

